package org.jkiss.dbeaver.ui.controls.findandreplace;

import org.jkiss.code.NotNull;

import java.util.function.Predicate;
import java.util.regex.Pattern;

public class SearchQuickFilterInfo {

    // Keep this as private fields for debugging purposes
    @NotNull
    private final String text;
    private final boolean caseSensitive;
    private final boolean useRegex;
    private final boolean wholeWord;

    @NotNull
    private final Pattern pattern;
    @NotNull
    private final Predicate<String> predicate;

    public SearchQuickFilterInfo(@NotNull String text, boolean caseSensitive, boolean useRegex, boolean wholeWord) {
        this.text = text;
        this.caseSensitive = caseSensitive;
        this.useRegex = useRegex;
        this.wholeWord = wholeWord;

        int patternFlags = caseSensitive ? 0 : Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE;
        String regex = useRegex ? text : Pattern.quote(text);

        if (!text.isEmpty()) {
            if (wholeWord) {
                if (Character.isLetterOrDigit(text.charAt(0))) {
                    regex = "\\b" + regex;
                }
                if (Character.isLetterOrDigit(text.charAt(text.length() - 1))) {
                    regex = regex + "\\b";
                }
            } else {
                regex += "";
            }
        }
        this.pattern = Pattern.compile(regex, patternFlags);
        this.predicate = this::stringMatch;
    }

    public boolean isCaseSensitive() {
        return this.caseSensitive;
    }

    public boolean isUseRegex() {
        return this.useRegex;
    }

    public boolean isWholeWord() {
        return this.wholeWord;
    }

    @NotNull
    public String getText() {
        return this.text;
    }

    @NotNull
    public Pattern getPattern() {
        return this.pattern;
    }

    @NotNull
    public Predicate<String> getPredicate() {
        return this.predicate;
    }

    public boolean stringMatch(@NotNull String string) {
        return this.pattern.matcher(string).find();
    }
}

import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import type { AnyNode, AnyNodeId, AnyNodeType } from '@pascal-app/core/schema'
import { pointInPolygon } from '@pascal-app/core/spatial-grid'
import { z } from 'zod'
import type { SceneOperations } from '../operations'
import { READ_ONLY_TOOL_ANNOTATIONS } from './annotations'
import { NodeIdSchema } from './schemas'

const ALL_NODE_TYPES = [
  'site',
  'building',
  'level',
  'wall',
  'fence',
  'zone',
  'slab',
  'ceiling',
  'roof',
  'roof-segment',
  'stair',
  'stair-segment',
  'item',
  'door',
  'window',
  'scan',
  'guide',
] as const

export const findNodesInput = {
  type: z.enum(ALL_NODE_TYPES).optional(),
  parentId: NodeIdSchema.optional(),
  levelId: NodeIdSchema.optional(),
  zoneId: NodeIdSchema.optional(),
}

export const findNodesOutput = {
  nodes: z.array(z.record(z.string(), z.unknown())),
}

/** Compute a representative 2D point (x, z) for zone-filtering. */
function getPointForZoneFilter(node: AnyNode): [number, number] | null {
  if (node.type === 'wall' || node.type === 'fence') {
    const [x1, z1] = node.start
    const [x2, z2] = node.end
    return [(x1 + x2) / 2, (z1 + z2) / 2]
  }
  if (
    node.type === 'item' ||
    node.type === 'door' ||
    node.type === 'window' ||
    node.type === 'building' ||
    node.type === 'stair' ||
    node.type === 'roof'
  ) {
    const [x, , z] = node.position
    return [x, z]
  }
  if (node.type === 'slab' || node.type === 'ceiling' || node.type === 'zone') {
    const poly = node.polygon as Array<[number, number]> | undefined
    if (!poly || poly.length === 0) return null
    let cx = 0
    let cz = 0
    for (const [x, z] of poly) {
      cx += x
      cz += z
    }
    return [cx / poly.length, cz / poly.length]
  }
  return null
}

export function registerFindNodes(server: McpServer, bridge: SceneOperations): void {
  server.registerTool(
    'find_nodes',
    {
      title: 'Find nodes',
      description:
        'Find nodes matching any combination of type, parentId, levelId, or zoneId filters.',
      inputSchema: findNodesInput,
      outputSchema: findNodesOutput,
      annotations: READ_ONLY_TOOL_ANNOTATIONS,
    },
    async (args) => {
      const { type, parentId, levelId, zoneId } = args as {
        type?: AnyNodeType
        parentId?: string
        levelId?: string
        zoneId?: string
      }

      // Delegate type/parent/level filtering to the bridge.
      const baseFilter: {
        type?: AnyNodeType
        parentId?: AnyNodeId
        levelId?: AnyNodeId
      } = {}
      if (type !== undefined) baseFilter.type = type
      if (parentId !== undefined) baseFilter.parentId = parentId as AnyNodeId
      if (levelId !== undefined) baseFilter.levelId = levelId as AnyNodeId
      let results = bridge.findNodes(baseFilter)

      // Zone-polygon filter: point-in-polygon on a representative 2D point.
      if (zoneId) {
        const zone = bridge.getNode(zoneId as AnyNodeId)
        if (zone?.type !== 'zone') {
          // Unknown zoneId → return empty list rather than throw; matches
          // typical "filter" semantics.
          results = []
        } else {
          const poly = zone.polygon
          results = results.filter((n) => {
            const pt = getPointForZoneFilter(n)
            if (!pt) return false
            return pointInPolygon(pt[0], pt[1], poly)
          })
        }
      }

      const payload = {
        nodes: results as unknown as Array<Record<string, unknown>>,
      }
      return {
        content: [{ type: 'text' as const, text: JSON.stringify(payload) }],
        structuredContent: payload,
      }
    },
  )
}

'use client'

import { type AnyNode, type BakeReplaceRenderer, nodeRegistry } from '@pascal-app/core'
import { createPortal } from '@react-three/fiber'
import { type ComponentType, Fragment, lazy, memo, type ReactNode, Suspense, useMemo } from 'react'
import type { Object3D } from 'three'

// Lazy components cached by their source so React.lazy isn't re-invoked per render.
const lazyCache = new WeakMap<BakeReplaceRenderer<AnyNode>, ComponentType<{ nodes: AnyNode[] }>>()

function getReplaceRenderer(
  source: BakeReplaceRenderer<AnyNode>,
): ComponentType<{ nodes: AnyNode[] }> {
  const cached = lazyCache.get(source)
  if (cached) return cached
  const Comp = lazy(source.module) as unknown as ComponentType<{ nodes: AnyNode[] }>
  lazyCache.set(source, Comp)
  return Comp
}

/**
 * Re-renders `bake: 'replace'` kinds (e.g. plugin trees) live over the baked GLB.
 * The baked static meshes are hidden by `GlbScene`; these nodes are grouped by
 * `(parent level, kind)` and each group is handed to the kind's collective
 * `bakeReplaceRenderer` (an instanced renderer), portaled into that level's baked
 * `Object3D`. Local-space instances therefore ride level stacking/explode for
 * free, and a forest stays a few instanced draw calls.
 *
 * Memoized: `GlbScene` re-renders each frame on camera move; `nodes` and
 * `identity` are stable refs, so this whole subtree short-circuits.
 */
export const GlbReplaceInstances = memo(function GlbReplaceInstances({
  nodes,
  identity,
}: {
  nodes: AnyNode[]
  identity: Map<string, Object3D>
}) {
  const byLevel = useMemo(() => {
    const levels = new Map<string, Map<string, AnyNode[]>>()
    for (const node of nodes) {
      const parentId = node.parentId
      if (!parentId) continue
      let byKind = levels.get(parentId)
      if (!byKind) {
        byKind = new Map()
        levels.set(parentId, byKind)
      }
      const list = byKind.get(node.type)
      if (list) list.push(node)
      else byKind.set(node.type, [node])
    }
    return levels
  }, [nodes])

  const portals: ReactNode[] = []
  byLevel.forEach((byKind, parentId) => {
    const anchor = identity.get(parentId)
    if (!anchor) return
    byKind.forEach((kindNodes, kind) => {
      const source = nodeRegistry.get(kind)?.bakeReplaceRenderer as
        | BakeReplaceRenderer<AnyNode>
        | undefined
      if (!source) return
      const Renderer = getReplaceRenderer(source)
      portals.push(
        <Fragment key={`${parentId}:${kind}`}>
          {createPortal(
            <Suspense fallback={null}>
              <Renderer nodes={kindNodes} />
            </Suspense>,
            anchor,
          )}
        </Fragment>,
      )
    })
  })
  return <>{portals}</>
})

import * as config from "trix/config"

import { assert, expectDocument, testGroup, testIf, triggerEvent } from "test/test_helper"
import { nextFrame } from "../test_helpers/timing_helpers"

const test = function() {
  testIf(config.input.getLevel() === 0, ...arguments)
}

testGroup("Level 0 input: HTML replacement", () =>
  testGroup("deleting with command+backspace", { template: "editor_empty" }, () => {
    test("from the end of a line", async () => {
      getEditor().loadHTML("<div>a</div><blockquote>b</blockquote><div>c</div>")
      getSelectionManager().setLocationRange({ index: 1, offset: 1 })
      await pressCommandBackspace({ replaceText: "b" })
      assert.locationRange({ index: 1, offset: 0 })
      assert.blockAttributes([ 0, 2 ], [])
      assert.blockAttributes([ 2, 3 ], [ "quote" ])
      assert.blockAttributes([ 3, 5 ], [])
      expectDocument("a\n\nc\n")
    })

    test("in the first block", async () => {
      getEditor().loadHTML("<div>a</div><blockquote>b</blockquote>")
      getSelectionManager().setLocationRange({ index: 0, offset: 1 })
      await pressCommandBackspace({ replaceText: "a" })
      assert.locationRange({ index: 0, offset: 0 })
      assert.blockAttributes([ 0, 1 ], [])
      assert.blockAttributes([ 1, 3 ], [ "quote" ])
      expectDocument("\nb\n")
    })

    test("from the middle of a line", async () => {
      getEditor().loadHTML("<div>a</div><blockquote>bc</blockquote><div>d</div>")
      getSelectionManager().setLocationRange({ index: 1, offset: 1 })
      await pressCommandBackspace({ replaceText: "b" })
      assert.locationRange({ index: 1, offset: 0 })
      assert.blockAttributes([ 0, 2 ], [])
      assert.blockAttributes([ 2, 4 ], [ "quote" ])
      assert.blockAttributes([ 4, 6 ], [])
      expectDocument("a\nc\nd\n")
    })

    test("from the middle of a line in a multi-line block", async () => {
      getEditor().loadHTML("<div>a</div><blockquote>bc<br>d</blockquote><div>e</div>")
      getSelectionManager().setLocationRange({ index: 1, offset: 1 })
      await pressCommandBackspace({ replaceText: "b" })
      assert.locationRange({ index: 1, offset: 0 })
      assert.blockAttributes([ 0, 2 ], [])
      assert.blockAttributes([ 2, 6 ], [ "quote" ])
      expectDocument("a\nc\nd\ne\n")
    })

    test("from the end of a list item", async () => {
      getEditor().loadHTML("<ul><li>a</li><li>b</li></ul>")
      getSelectionManager().setLocationRange({ index: 1, offset: 1 })
      await pressCommandBackspace({ replaceText: "b" })
      assert.locationRange({ index: 1, offset: 0 })
      assert.blockAttributes([ 0, 2 ], [ "bulletList", "bullet" ])
      assert.blockAttributes([ 2, 4 ], [ "bulletList", "bullet" ])
      expectDocument("a\n\n")
    })

    test("a character that is its text node's only data", async () => {
      getEditor().loadHTML("<div>a<br>b<br><strong>c</strong></div>")
      getSelectionManager().setLocationRange({ index: 0, offset: 3 })
      await pressCommandBackspace({ replaceText: "b" })
      assert.locationRange({ index: 0, offset: 2 })
      expectDocument("a\n\nc\n")
    })

    test("a formatted word", async () => {
      getEditor().loadHTML("<div>a<strong>bc</strong></div>")
      getSelectionManager().setLocationRange({ index: 0, offset: 4 })
      await pressCommandBackspace({ replaceElementWithText: "bc" })
      assert.locationRange({ index: 0, offset: 1 })
      expectDocument("a\n")
    })
  })
)

const pressCommandBackspace = async ({ replaceText, replaceElementWithText }) => {
  let previousSibling
  triggerEvent(document.activeElement, "keydown", { charCode: 0, keyCode: 8, which: 8, metaKey: true })
  const range = rangy.getSelection().getRangeAt(0)

  if (replaceElementWithText) {
    const element = getElementWithText(replaceElementWithText)
    previousSibling = element.previousSibling
    element.parentNode.removeChild(element)
    range.collapseAfter(previousSibling)
  } else {
    range.findText(replaceText, { direction: "backward" })
    range.splitBoundaries()

    const node = range.getNodes()[0]
    previousSibling = node.previousSibling
    const { nextSibling, parentNode } = node

    if (previousSibling?.nodeType === Node.COMMENT_NODE) {
      parentNode.removeChild(previousSibling)
    }

    node.data = ""
    parentNode.removeChild(node)

    if (!parentNode.hasChildNodes()) {
      parentNode.appendChild(document.createElement("br"))
    }

    range.collapseBefore(nextSibling ? nextSibling : parentNode.firstChild)
  }

  range.select()
  await nextFrame()
}

const getElementWithText = function (text) {
  for (const element of Array.from(document.activeElement.querySelectorAll("*"))) {
    if (element.innerText === text) {
      return element
    }
  }
  return null
}

